miss = []
for o, n in REPS:
    if o in t:
        t = t.replace(o, n)
    else:
        miss.append(o[:40])
io.open(P, "w", encoding="utf-8").write(t)
print("applied:", len(REPS) - len(miss), "misses:", len(miss))
for m in miss:
    print("  MISS:", m)

nb = re.sub(r"```.*?```", "", t.split("## 参考文献")[0], flags=re.S)
print("body CJK:", len(re.findall(r"[\u4e00-\u9fff]", nb)))
for s in re.split(r"\n(?=### |## )", nb):
    n = len(re.findall(r"[\u4e00-\u9fff]", s))
    if n:
        print("  %4d  %s" % (n, s.split("\n")[0][:28]))
